 IS DISTINCT FROM ROW(NEW.platform_name,NEW.slogan,NEW.default_municipality,NEW.default_state,NEW.currency,NEW.timezone,NEW.support_email,NEW.support_phone) THEN
 NEW.revision:=OLD.revision+1;NEW.updated_at:=clock_timestamp();
 ELSE NEW.revision:=OLD.revision;NEW.updated_at:=OLD.updated_at;END IF;RETURN NEW;
END;$$;
CREATE TRIGGER trg_app_global_config_bump_revision BEFORE UPDATE ON public.app_global_config FOR EACH ROW EXECUTE FUNCTION public.trg_fn_global_config_bump_revision();
COMMENT ON FUNCTION public.trg_fn_global_config_bump_revision() IS 'Incrementa revisão somente quando campos de negócio mudam.';
